#!/usr/bin/env python3
"""Focused regression harness for the libsoup header param-list overflow fix.

This does NOT build the whole project. It extracts the exact functions involved
from the supplied target source tree (libsoup/soup-headers.c) in the current
working directory, prepends minimal declarations for the small set of GLib
symbols they use, and links against the installed GLib runtime
(/usr/lib/x86_64-linux-gnu/libglib-2.0.so.0).

It then runs the upstream regression input for
soup_header_parse_semi_param_list() plus a handful of valid/negative cases.

Exit 0 => all assertions passed (and, under ASAN, no overflow was detected).
Non-zero => assertion failure, compile error, or ASAN-detected memory error.

Usage:
  python3 run_focused_test.py [--source libsoup/soup-headers.c] [--no-asan]
"""
from __future__ import annotations

import argparse
import os
import re
import subprocess
import sys
import tempfile
from pathlib import Path

GLIB_RUNTIME = "/usr/lib/x86_64-linux-gnu/libglib-2.0.so.0"

SHIM = r"""
#include <stddef.h>
#include <string.h>
#include <stdio.h>

typedef int gboolean;
typedef char gchar;
typedef unsigned char guchar;
typedef unsigned long gsize;
typedef signed long gssize;
typedef unsigned int guint;
typedef void *gpointer;
typedef const void *gconstpointer;
typedef struct _GError GError;
typedef struct _GHashTable GHashTable;
typedef void (*GDestroyNotify) (gpointer data);
typedef void (*GFunc) (gpointer data, gpointer user_data);
typedef guint (*GHashFunc) (gconstpointer key);
typedef gboolean (*GEqualFunc) (gconstpointer a, gconstpointer b);

typedef struct _GSList {
	gpointer data;
	struct _GSList *next;
} GSList;

/* GLib 2.x public GString layout. */
typedef struct _GString {
	gchar  *str;
	gsize   len;
	gsize   allocated_len;
} GString;

#ifndef TRUE
#define TRUE 1
#endif
#ifndef FALSE
#define FALSE 0
#endif

#define g_return_val_if_fail(expr, val) do { if (!(expr)) return (val); } while (0)

/* GLib runtime symbols (real implementations live in libglib-2.0.so.0). */
extern gchar *g_strndup (const gchar *str, gsize n);
extern void g_free (gpointer mem);
extern GSList *g_slist_prepend (GSList *list, gpointer data);
extern GSList *g_slist_reverse (GSList *list);
extern void g_slist_free (GSList *list);
extern void g_slist_free_full (GSList *list, GDestroyNotify free_func);
extern void g_slist_foreach (GSList *list, GFunc func, gpointer user_data);
extern GHashTable *g_hash_table_new_full (GHashFunc hash_func,
                                          GEqualFunc key_equal_func,
                                          GDestroyNotify key_destroy_func,
                                          GDestroyNotify value_destroy_func);
extern gboolean g_hash_table_lookup_extended (GHashTable *hash_table,
                                              gconstpointer lookup_key,
                                              gpointer *orig_key,
                                              gpointer *value);
extern void g_hash_table_replace (GHashTable *hash_table, gpointer key, gpointer value);
extern guint g_hash_table_size (GHashTable *hash_table);
extern gpointer g_hash_table_lookup (GHashTable *hash_table, gconstpointer key);
extern void g_hash_table_destroy (GHashTable *hash_table);
extern GString *g_string_new (const gchar *init);
extern GString *g_string_assign (GString *string, const gchar *rval);
extern gchar *g_string_free (GString *string, gboolean free_segment);
extern int g_ascii_strncasecmp (const gchar *s1, const gchar *s2, gsize n);
extern int g_ascii_strcasecmp (const gchar *s1, const gchar *s2);
extern gchar g_ascii_toupper (gchar c);
extern gchar *g_convert_with_fallback (const gchar *str, gssize len,
                                       const gchar *to_codeset,
                                       const gchar *from_codeset,
                                       const gchar *fallback,
                                       gsize *bytes_read,
                                       gsize *bytes_written,
                                       GError **error);

/* g_ascii_isxdigit / g_ascii_isspace are inline macros in GLib headers. */
static gboolean
g_ascii_isxdigit (gchar c)
{
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F');
}

static gboolean
g_ascii_isspace (gchar c)
{
	return c == ' ' || c == '\t' || c == '\n' || c == '\v' || c == '\f' || c == '\r';
}

/* ---- Verbatim from supplied target libsoup/soup-misc.c ---- */
guint
soup_str_case_hash (gconstpointer key)
{
	const char *p = key;
	guint h = g_ascii_toupper (*p);

	if (h)
		for (p += 1; *p != '\0'; p++)
			h = (h << 5) - h + g_ascii_toupper (*p);

	return h;
}

gboolean
soup_str_case_equal (gconstpointer v1, gconstpointer v2)
{
	return g_ascii_strcasecmp ((const char *) v1, (const char *) v2) == 0;
}

/* ---- Verbatim from supplied target libsoup/soup-uri.c ---- */
#define XDIGIT(c) ((c) <= '9' ? (c) - '0' : ((c) & 0x4F) - 'A' + 10)
#define HEXCHAR(s) ((XDIGIT (s[1]) << 4) + XDIGIT (s[2]))

char *
soup_uri_decoded_copy (const char *part, int length, int *decoded_length)
{
	unsigned char *s, *d;
	char *decoded;

	g_return_val_if_fail (part != NULL, NULL);

	decoded = g_strndup (part, length);
	s = d = (unsigned char *)decoded;
	do {
		if (*s == '%') {
			if (s[1] == '\0' ||
			    s[2] == '\0' ||
			    !g_ascii_isxdigit (s[1]) ||
			    !g_ascii_isxdigit (s[2])) {
				*d++ = *s;
				continue;
			}
			*d++ = HEXCHAR (s);
			s += 2;
		} else
			*d++ = *s;
	} while (*s++);

	if (decoded_length)
		*decoded_length = d - (unsigned char *)decoded - 1;

	return decoded;
}

char *
soup_uri_decode (const char *part)
{
	g_return_val_if_fail (part != NULL, NULL);

	return soup_uri_decoded_copy (part, strlen (part), NULL);
}
"""

MAIN = r"""
static int failures = 0;

static void
check_str (const char *label, GHashTable *params, const char *key, const char *expected)
{
	const char *actual = g_hash_table_lookup (params, key);

	if (expected == NULL) {
		if (actual != NULL) {
			printf ("FAIL %s: key '%s' expected NULL got '%s'\n",
				label, key, actual);
			failures++;
		}
	} else if (actual == NULL || strcmp (actual, expected) != 0) {
		printf ("FAIL %s: key '%s' expected '%s' got '%s'\n",
			label, key, expected, actual ? actual : "(null)");
		failures++;
	}
}

static void
check_size (const char *label, GHashTable *params, guint expected)
{
	guint actual = g_hash_table_size (params);
	if (actual != expected) {
		printf ("FAIL %s: expected size %u got %u\n", label, expected, actual);
		failures++;
	}
}

/* Upstream regression input from tests/header-parsing-test.c */
#define REGRESSION_HEADER \
	"invalid*=\x69\x27\x27\x93\x93\x93\x93\xff\x61\x61\x61\x61\x61\x61\x61\x62\x63\x64\x65\x0a; " \
	"filename*=iso-8859-1''\x69\x27\x27\x93\x93\x93\x93\xff\x61\x61\x61\x61\x61\x61\x61\x62\x63\x64\x65\x0a; foo"

#define REG_INVALID  "\302\223\302\223\302\223\302\223\303\277aaaaaaabcde"
#define REG_FILENAME "i''\302\223\302\223\302\223\302\223\303\277aaaaaaabcde"

int
main (void)
{
	GHashTable *p;

	/* 1. upstream invalid-UTF-8 regression, non-strict */
	p = parse_param_list (REGRESSION_HEADER, ';', FALSE);
	if (!p) {
		printf ("FAIL regression-nonstrict: NULL table\n");
		failures++;
	} else {
		check_size ("regression-nonstrict", p, 3);
		check_str ("regression-nonstrict", p, "filename", REG_FILENAME);
		check_str ("regression-nonstrict", p, "invalid", REG_INVALID);
		check_str ("regression-nonstrict", p, "foo", NULL);
		g_hash_table_destroy (p);
	}

	/* 2. upstream invalid-UTF-8 regression, strict */
	p = parse_param_list (REGRESSION_HEADER, ';', TRUE);
	if (!p) {
		printf ("FAIL regression-strict: NULL table\n");
		failures++;
	} else {
		check_size ("regression-strict", p, 3);
		check_str ("regression-strict", p, "filename", REG_FILENAME);
		check_str ("regression-strict", p, "invalid", REG_INVALID);
		check_str ("regression-strict", p, "foo", NULL);
		g_hash_table_destroy (p);
	}

	/* 3. valid quoted-string decoding */
	p = parse_param_list ("form-data; name=\"fieldName\"; filename=\"filename.jpg\"", ';', TRUE);
	if (!p) { printf ("FAIL quoted: NULL table\n"); failures++; }
	else {
		check_size ("quoted", p, 3);
		check_str ("quoted", p, "name", "fieldName");
		check_str ("quoted", p, "filename", "filename.jpg");
		g_hash_table_destroy (p);
	}

	/* 4. valid RFC 5987 UTF-8 decoding */
	p = parse_param_list ("attachment; filename*=UTF-8''t%C3%A9st.txt", ';', TRUE);
	if (!p) { printf ("FAIL utf8: NULL table\n"); failures++; }
	else {
		check_str ("utf8", p, "filename", "t\xC3\xA9st.txt");
		g_hash_table_destroy (p);
	}

	/* 5. valid RFC 5987 iso-8859-1 percent-encoded decoding */
	p = parse_param_list ("attachment; filename=\"test.txt\"; filename*=iso-8859-1''t%E9st.txt", ';', TRUE);
	if (!p) { printf ("FAIL iso: NULL table\n"); failures++; }
	else {
		check_str ("iso", p, "filename", "t\xC3\xA9st.txt");
		g_hash_table_destroy (p);
	}

	/* 6. strict duplicate rejection returns NULL */
	p = parse_param_list ("form-data; form-data; filename=\"filename.jpg\"", ';', TRUE);
	if (p != NULL) { printf ("FAIL strict-dup: expected NULL table\n"); failures++; g_hash_table_destroy (p); }

	/* 7. simple values */
	p = parse_param_list ("UserID=JohnDoe; Max-Age=3600; Version=1", ';', TRUE);
	if (!p) { printf ("FAIL simple: NULL table\n"); failures++; }
	else {
		check_size ("simple", p, 3);
		check_str ("simple", p, "UserID", "JohnDoe");
		check_str ("simple", p, "Max-Age", "3600");
		check_str ("simple", p, "Version", "1");
		g_hash_table_destroy (p);
	}

	if (failures) {
		printf ("FOCUSED TESTS: %d FAILURE(S)\n", failures);
		return 1;
	}
	printf ("FOCUSED TESTS: ALL PASSED\n");
	return 0;
}
"""


def extract (source_text: str) -> tuple[str, str]:
    m_helpers = re.search(
        r"static const char \*\nskip_lws .*?(?=/\*\*\n \* soup_header_parse_list:)",
        source_text, re.S)
    if not m_helpers:
        raise SystemExit("could not extract skip_lws..parse_list region")
    m_decode = re.search(
        r"static void\ndecode_quoted_string.*?(?=/\*\*\n \* soup_header_parse_param_list:)",
        source_text, re.S)
    if not m_decode:
        raise SystemExit("could not extract decode_* + parse_param_list region")
    return m_helpers.group(0), m_decode.group(0)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--source", default="libsoup/soup-headers.c")
    ap.add_argument("--no-asan", action="store_true")
    args = ap.parse_args()

    src_path = Path(args.source)
    if not src_path.is_file():
        print(f"source not found: {src_path}", file=sys.stderr)
        return 2
    source_text = src_path.read_text(encoding="utf-8", errors="replace")
    has_inplace = "decode_rfc5987_inplace" in source_text
    helpers, decode = extract(source_text)

    c_code = SHIM + "\n/* ---- extracted verbatim from supplied target " + str(src_path) + " ---- */\n" \
        + helpers + "\n" + decode + "\n" + MAIN

    tmp = Path(tempfile.mkdtemp(prefix="soup-port-focus-"))
    c_file = tmp / "focus.c"
    out = tmp / "focus"
    c_file.write_text(c_code, encoding="utf-8")

    compile_cmd = ["gcc", "-std=gnu99", "-g", "-O0", "-Wall", "-o", str(out), str(c_file),
                   GLIB_RUNTIME, "-lpthread", "-ldl", "-lm"]
    if not args.no_asan:
        compile_cmd.insert(1, "-fsanitize=address")
    proc = subprocess.run(compile_cmd, capture_output=True, text=True)
    print("### source mode:", "PATCHED (inplace/GString)" if has_inplace else "BASELINE (char*)")
    print("### compile:", " ".join(compile_cmd))
    print("### compile exit:", proc.returncode)
    if proc.stderr.strip():
        print(proc.stderr, end="")
    if proc.returncode != 0:
        return 3

    env = dict(os.environ)
    env["ASAN_OPTIONS"] = "detect_leaks=0:abort_on_error=0:halt_on_error=1"
    run = subprocess.run([str(out)], capture_output=True, text=True, env=env, timeout=120)
    print("### run exit:", run.returncode)
    if run.stdout:
        print(run.stdout, end="")
    if run.stderr:
        print(run.stderr, end="")
    return run.returncode


if __name__ == "__main__":
    raise SystemExit(main())

